mapper.select:
SELECT s.id, s.level, s.department_id, s.state AS staff_state, u.email, u.sign_up_time, d.name AS dept_name,
       (SELECT COUNT(*) FROM tickets t WHERE t.assignee_id = s.id AND t.closed = 0) AS ticket_assigned_count
FROM staff s JOIN users u ON u.id = s.id LEFT JOIN departments d ON d.id = s.department_id
WHERE 1=1
AND u.email LIKE '%' || #{emailKeyword} || '%'
AND s.department_id = #{departmentId}
AND s.level = #{level}
AND u.sign_up_time >= #{registerDateFrom}
AND u.sign_up_time <= #{registerDateTo}
ORDER BY ${sortBy} DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM staff s JOIN users u ON u.id = s.id WHERE 1=1
AND u.email LIKE '%' || #{emailKeyword} || '%'
AND s.department_id = #{departmentId}
AND s.level = #{level}
AND u.sign_up_time >= #{registerDateFrom}
AND u.sign_up_time <= #{registerDateTo}
